export enum LockType {
	User = 0,
	App = 1,
	Token = 2,
}

export type LockState = {
	isLocked: boolean,
	lockOwner: string,
	lockOwnerDisplayName: string,
	lockOwnerType: LockType,
	lockOwnerEditor: string,
	lockTime: number,
}
